import {jest} from '@jest/globals';
import Ajv from 'ajv';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry input validation', () => {
  it('names a static tool whose schema cannot be compiled at registration', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_weather',
          description: 'Has an invalid schema',
          inputSchema: {type: 'not-a-json-schema-type'},
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_weather/);
  });

  it('returns a rejection when a required property is missing', async () => {
    const registry = new ToolRegistry();
    const execute = jest.fn(async () => 'sunny');
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      execute
    );

    const response = await registry.execute('get_weather', {});
    const executorCalls = execute.mock.calls;

    expect({result: response.result, executorCalls: executorCalls.length}).toEqual({
      result: "Input validation failed: required property 'location' is missing",
      executorCalls: 0,
    });
  });

  it('describes a wrong property type without exposing its value', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'find_customer',
        description: 'Find a customer',
        inputSchema: {
          type: 'object',
          properties: {customerId: {type: 'string'}},
          required: ['customerId'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'found';
      }
    );

    const response = await registry.execute('find_customer', {customerId: 123456789});

    expect({result: response.result, executorCalls}).toEqual({
      result: "Input validation failed: property '/customerId' must be string",
      executorCalls: 0,
    });
  });

  it('reuses a function-valued source validator for the same schema object', async () => {
    const registry = new ToolRegistry();
    const inputSchema = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    const execute = jest.fn(async () => 'sunny');
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    registry.register(
      () => ({
        name: 'get_dynamic_weather',
        description: 'Get weather from a dynamic definition',
        inputSchema,
      }),
      execute
    );

    try {
      await registry.execute('get_dynamic_weather', {location: 'Berlin'});
      await registry.execute('get_dynamic_weather', {location: 'Paris'});

      expect(compile).toHaveBeenCalledTimes(1);
      expect(execute).toHaveBeenCalledTimes(2);
    } finally {
      compile.mockRestore();
    }
  });
});
# Tool Input Validation

| Field  | Value                |
| ------ | -------------------- |
| Issue  | re-cinq/HALEngine#37 |
| Status | In Progress          |

Every tool registered in `src/orchestration/tools/registry.ts` declares a JSON Schema `inputSchema` that is forwarded to the configured AI provider, and `ToolRegistry.execute` validates the model-supplied `input` against that schema before calling the tool's executor. When validation fails, `execute` returns a rejection `ToolResponse` describing what was wrong rather than throwing, so the orchestrator feeds the failure back to the model as a `tool_result` within the existing tool-round budget.

## Validation at execute time

- When `input` omits a property listed in `required`, `ToolRegistry.execute` returns a `ToolResponse` whose `result` names the missing property as required and never invokes the executor ([validated by: rejects input missing a required property with a ToolResponse and never calls the executor](../../src/orchestration/tools/registry.acceptance.test.ts#L16), [returns a rejection when a required property is missing](../../src/orchestration/tools/registry.test.ts#L21)).
- When `input` supplies a property whose value does not match its declared JSON Schema type, `ToolRegistry.execute` returns a `ToolResponse` naming the failing field path and expected type without invoking the executor, and neither `result` nor the emitted log record contains the offending property value ([validated by: rejects a wrong-typed property naming the field and expected type without leaking the offending value to the result or logs](../../src/orchestration/tools/registry.acceptance.test.ts#L46), [describes a wrong property type without exposing its value](../../src/orchestration/tools/registry.test.ts#L46)).
- When `input` satisfies `required`, declared property types and `enum`, `ToolRegistry.execute` invokes the executor once and passes the input object through unchanged — including undeclared extra properties — without injecting `additionalProperties: false`, coercing types or applying defaults.
- When `ToolRegistry.execute` is called with a tool name that has not been registered, it throws `Unknown tool: <name>` because an unregistered tool is a programming or configuration error rather than a recoverable input mistake.

## Schema compilation and caching

- A static `ToolDefinition` has its `inputSchema` compiled once at `register` time, so a schema that is not valid JSON Schema throws synchronously from `register` with an error message naming the offending tool ([validated by: throws at register time naming the tool when a static inputSchema cannot be compiled](../../src/orchestration/tools/registry.acceptance.test.ts#L94), [names a static tool whose schema cannot be compiled at registration](../../src/orchestration/tools/registry.test.ts#L6)).
- A static tool's `inputSchema` is compiled at `register` time and reused on every `execute` call without re-reading or re-compiling `definition.inputSchema`.
- A function-valued `ToolDefinitionSource` resolves its definition on each `execute` call and validates against the `inputSchema` returned for that call, caching compiled validators by schema object reference (`WeakMap`) so distinct returned schemas each enforce their own rules ([reuses a function-valued source validator for the same schema object](../../src/orchestration/tools/registry.test.ts#L73)).

## Orchestrator tool-loop recovery

- Because a schema rejection returns a `ToolResponse` instead of throwing, `src/orchestration/chatOrchestrator.ts` sends the rejection `result` back to the provider as a `tool_result` message, allowing the model to issue a corrected tool call on the next round and complete the turn within `maxToolRounds` ([validated by: returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round](../../src/orchestration/tools/registry.acceptance.test.ts#L112)).
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';
import Ajv from 'ajv';
import type {ErrorObject, ValidateFunction} from 'ajv';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validate?: ValidateFunction;
}

const ajv = new Ajv({strict: false, validateFormats: false} as never);

const validationMessage = (errors: ErrorObject[] | null | undefined): string => {
  const error = errors?.[0];
  if (error?.keyword === 'required' && 'missingProperty' in error.params) {
    const property = String(error.params.missingProperty);
    return `Input validation failed: required property '${property}' is missing`;
  }
  if (error?.keyword === 'type' && 'type' in error.params) {
    const rawPath =
      (error as ErrorObject & {dataPath?: string; instancePath?: string}).instancePath ??
      (error as ErrorObject & {dataPath?: string}).dataPath ??
      '';
    const path = rawPath.startsWith('.') ? `/${rawPath.slice(1).replaceAll('.', '/')}` : rawPath;
    return `Input validation failed: property '${path}' must be ${String(error.params.type)}`;
  }
  return 'Input validation failed';
};

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly dynamicValidators = new WeakMap<Record<string, unknown>, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let validate: ValidateFunction | undefined;
    try {
      validate = typeof definition === 'function' ? undefined : ajv.compile(resolved.inputSchema);
    } catch (error) {
      throw new Error(`Invalid input schema for tool '${resolved.name}'`, {cause: error});
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, validate});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Executes schema-valid input; see specs/hal-engine-tool-input-validation/spec.md for the rejection contract. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    let validate = tool.validate ?? this.dynamicValidators.get(definition.inputSchema);
    if (!validate) {
      validate = ajv.compile(definition.inputSchema);
      this.dynamicValidators.set(definition.inputSchema, validate);
    }
    if (!validate(input)) {
      return {result: validationMessage(validate.errors)};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
